CREATE ALGORITHM=UNDEFINED DEFINER=`hcfi`@`%` SQL SECURITY DEFINER VIEW `all_budgetlines` AS select `account`.`Name` AS `Account_Name`,`account`.`ID` AS `Account_ID`,`subproject`.`Name` AS `Subproject_Name`,`subproject`.`ID` AS `Subproject_ID`,`project`.`ID` AS `project_ID`,`project`.`Name` AS `project_name`,`city`.`Name` AS `City_Name`,`city`.`ID` AS `City_ID`,`budget_line`.`ID` AS `budget_line_ID`,`budget`.`ID` AS `budget_ID`,`budget`.`Name` AS `budget_Name`,`tilltypes`.`Name` AS `BudgetType`,`tilltypes`.`ID` AS `BudgetType_ID`,`line`.`ID` AS `line_ID`,`line`.`Name` AS `line_Name`,`linecategory`.`ID` AS `linecategory_ID`,`linecategory`.`Name` AS `linecategory_Name`,`linecategorytype`.`Name` AS `linecategory_Type`,(case `linecategory`.`Kind` when 0 then 'Profit' else 'Budget' end) AS `linecategory_Kind`,`budget_line`.`Unit` AS `Unit`,`budget_line`.`Timing` AS `Timing`,`budget_line`.`Price` AS `Price`,ifnull(((`budget_line`.`Unit` * `budget_line`.`Timing`) * `budget_line`.`Price`),0) AS `Expected_Total`,(select ifnull(sum((case when (`action`.`currency_tilltype_id` = 2) then `action`.`Amount` else (`action`.`Amount` / `all_avgrates`.`Value`) end)),0) from ((`action` left join `actiontype` on((`action`.`AType_ID` = `actiontype`.`id`))) left join `all_avgrates` on((`action`.`Rate_ID` = `all_avgrates`.`id`))) where ((`actiontype`.`shortname` in ('E','Ex')) and (`action`.`BudgetLine_ID` = `budget_line`.`ID`) and (date_format(`action`.`ActionDate`,'%m/%Y') = date_format(str_to_date(concat('01/',(case when (`budget_date__monthes`.`month` < 10) then '0' else '' end),`budget_date__monthes`.`month`,'/',`budget_date__monthes`.`year`),'%d/%m/%Y'),'%m/%Y')))) AS `Expenditures`,`budget`.`BeginDate` AS `budget_BeginDate`,`budget`.`EndDate` AS `budget_EndDate`,str_to_date(concat('01-',(case when (`budget_date__monthes`.`month` < 10) then '0' else '' end),`budget_date__monthes`.`month`,'-',`budget_date__monthes`.`year`),'%d-%m-%Y') AS `BudgetMonthes`,(select ifnull(sum((case when (`action`.`currency_tilltype_id` = 2) then `action`.`Amount` else (`action`.`Amount` / `all_avgrates`.`Value`) end)),0) from ((`action` left join `actiontype` on((`action`.`AType_ID` = `actiontype`.`id`))) left join `all_avgrates` on((`action`.`Rate_ID` = `all_avgrates`.`id`))) where ((`actiontype`.`shortname` in ('E','Ex')) and (`action`.`BudgetLine_ID` = `budget_line`.`ID`))) AS `Expenditures_With_Out_Of_Date` from ((((((((((`budget_line` left join `budget` on((`budget_line`.`Budget_ID` = `budget`.`ID`))) left join `account` on((`account`.`ID` = `budget`.`Account_ID`))) left join `subproject` on((`account`.`SubProject_ID` = `subproject`.`ID`))) left join `project` on((`project`.`ID` = `subproject`.`Project_ID`))) left join `city` on((`subproject`.`City_ID` = `city`.`ID`))) left join `tilltypes` on((`budget`.`Budget_Type_ID` = `tilltypes`.`ID`))) left join `line` on((`budget_line`.`Line_ID` = `line`.`ID`))) left join `linecategory` on((`linecategory`.`ID` = `line`.`Category_ID`))) left join `linecategorytype` on((`linecategorytype`.`ID` = `linecategory`.`Type_ID`))) join `budget_date__monthes` on((`budget_date__monthes`.`budget_id` = `budget`.`ID`))) where (cast(concat_ws('-',`budget_date__monthes`.`year`,`budget_date__monthes`.`month`,dayofmonth(`budget`.`BeginDate`)) as date) between cast(`budget`.`BeginDate` as date) and cast(`budget`.`EndDate` as date)) order by `budget`.`ID`,`budget_line`.`ID`,`budget_date__monthes`.`year`,`budget_date__monthes`.`month`
